/**
 * Timeline maths. No copy, no React, no Dexie — everything here is a pure
 * function over plain dates so it can be unit-tested without a database.
 *
 * Two rules shape the whole module:
 *   - Nothing is invented. Every entry, every milestone, and every heat cell
 *     comes from something the couple actually wrote down.
 *   - Counting is never grading. `level()` produces a shade, not a verdict, and
 *     nothing here ever combines the sources into a single "how are we doing"
 *     number (CLAUDE.md — no relationship score).
 */

export type EntrySource = 'memory' | 'event'

export interface TimelineEntry {
  id: string
  /** yyyy-MM-dd */
  date: string
  title: string
  source: EntrySource
  isMilestone: boolean
  story?: string
}

export interface MonthGroup {
  /** yyyy-MM */
  month: string
  items: TimelineEntry[]
}

export interface YearGroup {
  /** yyyy */
  year: string
  months: MonthGroup[]
}

const DAY_MS = 86_400_000

/** yyyy-MM-dd from a UTC timestamp. */
function isoDay(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10)
}

/**
 * Newest first, at every level. A memories screen is read backwards from now —
 * the couple wants last month before they want 2019.
 */
export function groupByYearMonth(entries: TimelineEntry[]): YearGroup[] {
  const byMonth = new Map<string, TimelineEntry[]>()
  for (const e of entries) {
    const month = e.date.slice(0, 7)
    const bucket = byMonth.get(month)
    if (bucket) bucket.push(e)
    else byMonth.set(month, [e])
  }

  const byYear = new Map<string, MonthGroup[]>()
  for (const month of [...byMonth.keys()].sort((a, b) => b.localeCompare(a))) {
    const items = byMonth.get(month)!.sort(
      // Same-day entries fall back to title so the order is stable between
      // renders; two records written the same day have no meaningful sequence.
      (a, b) => b.date.localeCompare(a.date) || a.title.localeCompare(b.title),
    )
    const year = month.slice(0, 4)
    const bucket = byYear.get(year)
    if (bucket) bucket.push({ month, items })
    else byYear.set(year, [{ month, items }])
  }

  return [...byYear.entries()]
    .sort((a, b) => b[0].localeCompare(a[0]))
    .map(([year, months]) => ({ year, months }))
}

/** Years that actually hold something, newest first, plus `include` (usually today's). */
export function yearsWithData(dates: string[], include: number): number[] {
  const years = new Set<number>([include])
  for (const d of dates) {
    const y = Number(d.slice(0, 4))
    if (Number.isFinite(y)) years.add(y)
  }
  return [...years].sort((a, b) => b - a)
}

// ---------------------------------------------------------------------------
// Heatmap
// ---------------------------------------------------------------------------

export interface DayCount {
  memories: number
  events: number
  /** Days both partners showed up. Never split per person (ART_BIBLE §7). */
  pairDays: number
  total: number
}

export interface DaySources {
  memories: string[]
  events: string[]
  pairDays: string[]
}

const EMPTY_COUNT: DayCount = { memories: 0, events: 0, pairDays: 0, total: 0 }

/** Per-day tallies for one calendar year, keyed by yyyy-MM-dd. */
export function dayCounts(sources: DaySources, year: number): Map<string, DayCount> {
  const prefix = String(year)
  const out = new Map<string, DayCount>()
  const bump = (date: string, field: 'memories' | 'events' | 'pairDays') => {
    if (date.slice(0, 4) !== prefix) return
    const key = date.slice(0, 10)
    const cur = out.get(key) ?? { ...EMPTY_COUNT }
    cur[field] += 1
    cur.total += 1
    out.set(key, cur)
  }
  for (const d of sources.memories) bump(d, 'memories')
  for (const d of sources.events) bump(d, 'events')
  for (const d of sources.pairDays) bump(d, 'pairDays')
  return out
}

export type HeatLevel = 0 | 1 | 2 | 3 | 4

/**
 * Shade for a day, relative to the busiest day of the same year. Relative
 * rather than absolute because a couple logging twice a week and a couple
 * logging daily should both get a readable grid.
 */
export function level(count: number, max: number): HeatLevel {
  if (count <= 0 || max <= 0) return 0
  return Math.min(4, Math.ceil((count / max) * 4)) as HeatLevel
}

export interface HeatCell {
  /** null for padding cells before 1 Jan and after 31 Dec. */
  date: string | null
  count: DayCount
  level: HeatLevel
}

const PAD: HeatCell = { date: null, count: EMPTY_COUNT, level: 0 }

/**
 * A year as columns of seven days, Monday at the top — Indonesian calendars
 * start the week on Monday, so a Sunday-first grid reads wrong here.
 *
 * Dates are built in UTC on purpose: constructing them in local time makes the
 * grid slide by a day across a DST boundary, which silently mis-files entries.
 */
export function heatmapWeeks(year: number, counts: Map<string, DayCount>): HeatCell[][] {
  let max = 0
  for (const c of counts.values()) max = Math.max(max, c.total)

  const start = Date.UTC(year, 0, 1)
  const end = Date.UTC(year, 11, 31)
  const lead = (new Date(start).getUTCDay() + 6) % 7 // Mon=0 … Sun=6

  const weeks: HeatCell[][] = []
  let week: HeatCell[] = Array.from({ length: lead }, () => PAD)
  for (let ms = start; ms <= end; ms += DAY_MS) {
    const date = isoDay(ms)
    const count = counts.get(date) ?? EMPTY_COUNT
    week.push({ date, count, level: level(count.total, max) })
    if (week.length === 7) {
      weeks.push(week)
      week = []
    }
  }
  while (week.length > 0 && week.length < 7) week.push(PAD)
  if (week.length) weeks.push(week)
  return weeks
}

/** Column (1-based, for `grid-column-start`) where each month first appears. */
export function monthColumns(weeks: HeatCell[][]): { month: number; column: number }[] {
  const out: { month: number; column: number }[] = []
  weeks.forEach((week, i) => {
    for (const cell of week) {
      if (!cell.date) continue
      const month = Number(cell.date.slice(5, 7))
      if (out.some((m) => m.month === month)) continue
      out.push({ month, column: i + 1 })
    }
  })
  return out
}

/** Every day with something on it, oldest first — the screen-reader table. */
export function activeDays(counts: Map<string, DayCount>): { date: string; count: DayCount }[] {
  return [...counts.entries()]
    .filter(([, c]) => c.total > 0)
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([date, count]) => ({ date, count }))
}

// ---------------------------------------------------------------------------
// Milestones
// ---------------------------------------------------------------------------

export interface MilestoneMark {
  id: string
  title: string
  /** The day it actually happened. */
  date: string
  /** The day inside the selected year that marks it. */
  markDate: string
  /** Whole years between `date` and `markDate`. 0 means this is the day itself. */
  years: number
  story?: string
}

export interface MilestoneInput {
  id: string
  title: string
  date: string
  story?: string
}

/**
 * Milestones falling inside `year`: the originals that happened that year, plus
 * the anniversary of every earlier one.
 *
 * Nothing is guessed. "First date" or "first trip" only appears because someone
 * ticked *penanda* on a memory with that title — the app never decides that a
 * date was significant on the couple's behalf.
 */
export function milestonesIn(memories: MilestoneInput[], year: number): MilestoneMark[] {
  const marks: MilestoneMark[] = []
  for (const m of memories) {
    const origin = Number(m.date.slice(0, 4))
    if (!Number.isFinite(origin) || origin > year) continue
    marks.push({
      id: `${m.id}@${year}`,
      title: m.title,
      date: m.date,
      markDate: anniversaryIn(m.date, year),
      years: year - origin,
      ...(m.story ? { story: m.story } : {}),
    })
  }
  return marks.sort((a, b) => a.markDate.localeCompare(b.markDate) || a.title.localeCompare(b.title))
}

/**
 * Same day, different year. 29 February moves to 28 February in a common year —
 * the alternative is 1 March, which puts the anniversary in the wrong month.
 */
export function anniversaryIn(date: string, year: number): string {
  const md = date.slice(5, 10)
  if (md === '02-29' && !isLeap(year)) return `${year}-02-28`
  return `${year}-${md}`
}

export function isLeap(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0
}
