import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { useLiveQuery } from 'dexie-react-hooks'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db } from '@/db/db'
import type { CalendarEvent, Memory } from '@/types/domain'
import { useI18n, type MessageKey } from '@/i18n'
import { fmtDate } from '@/i18n/format'
import type { DayRecord } from '@/features/companion/streak'
import {
  activeDays,
  dayCounts,
  groupByYearMonth,
  heatmapWeeks,
  milestonesIn,
  monthColumns,
  yearsWithData,
  type DayCount,
  type HeatCell,
  type TimelineEntry,
} from './model'
import './timeline.css'

type View = 'list' | 'heat' | 'marks'
const VIEWS: { id: View; label: MessageKey }[] = [
  { id: 'list', label: 'timeline.tab.list' },
  { id: 'heat', label: 'timeline.tab.heat' },
  { id: 'marks', label: 'timeline.tab.marks' },
]

/**
 * Linimasa — the shared history, three ways.
 *
 * Reads go through `useOwned()`, so a private memory belonging to a partner is
 * already gone before this file sees it. The one direct Dexie read is the
 * companion's day log in `settings`, which holds no envelope and no content —
 * only "both of us showed up on this date" (same read as `Companion.tsx`).
 */
export default function Timeline() {
  const { t } = useI18n()
  const { profile } = useSession()
  const me = profile?.id
  const [view, setView] = useState<View>('list')
  const [year, setYear] = useState(() => new Date().getFullYear())

  const memories = useOwned<Memory>('memories', me)
  const events = useOwned<CalendarEvent>('events', me)
  const pairDayDates = useLiveQuery(async () => {
    const row = await db.settings.get('temu.days')
    const days = (row?.value as DayRecord[] | undefined) ?? []
    // A pair-day is a day *both* halves landed on. Never split per person.
    return days.filter((d) => d.a && d.b).map((d) => d.date)
  }, [])

  const entries = useMemo<TimelineEntry[]>(() => {
    const fromMemories = (memories ?? []).map((m) => ({
      id: m.id,
      date: m.date,
      title: m.title,
      source: 'memory' as const,
      isMilestone: m.isMilestone,
      ...(m.story ? { story: m.story } : {}),
    }))
    const fromEvents = (events ?? []).map((e) => ({
      id: e.id,
      date: e.date,
      // A co-owned private event shows its mask, exactly as the calendar does.
      title: e.visibility === 'private' && e.ownerProfileId !== me ? (e.maskedTitle ?? e.title) : e.title,
      source: 'event' as const,
      isMilestone: false,
      ...(e.note ? { story: e.note } : {}),
    }))
    return [...fromMemories, ...fromEvents]
  }, [memories, events, me])

  const years = useMemo(
    () => yearsWithData(entries.map((e) => e.date), new Date().getFullYear()),
    [entries],
  )

  const counts = useMemo(
    () =>
      dayCounts(
        {
          memories: (memories ?? []).map((m) => m.date),
          events: (events ?? []).map((e) => e.date),
          pairDays: pairDayDates ?? [],
        },
        year,
      ),
    [memories, events, pairDayDates, year],
  )

  if (!profile || !me) return null

  const hasAnything = entries.length > 0 || (pairDayDates ?? []).length > 0

  return (
    <div className="stack">
      <h1>{t('timeline.title')}</h1>
      <p className="card__hint">{t('timeline.subtitle')}</p>

      <div className="row row--between">
        <div className="segmented" role="group" aria-label={t('timeline.tabsLabel')}>
          {VIEWS.map((v) => (
            <button key={v.id} type="button" aria-pressed={view === v.id} onClick={() => setView(v.id)}>
              {t(v.label)}
            </button>
          ))}
        </div>
        <YearPicker year={year} years={years} onChange={setYear} />
      </div>

      {!hasAnything ? (
        <Card>
          <EmptyState
            icon="memories"
            title={t('timeline.empty')}
            hint={t('timeline.emptyHint')}
            action={
              <Link className="btn btn--sm" to="/momen?baru=1">
                <Icon name="plus" size={16} /> {t('mem.save')}
              </Link>
            }
          />
        </Card>
      ) : view === 'list' ? (
        <ListView entries={entries.filter((e) => e.date.startsWith(String(year)))} year={year} />
      ) : view === 'heat' ? (
        <HeatView year={year} counts={counts} />
      ) : (
        <MarksView memories={memories ?? []} year={year} />
      )}
    </div>
  )
}

function YearPicker({
  year,
  years,
  onChange,
}: {
  year: number
  years: number[]
  onChange: (y: number) => void
}) {
  const { t } = useI18n()
  return (
    <div style={{ minWidth: 120 }}>
      <Field label={t('timeline.year')}>
        {(p) => (
          <select
            {...p}
            aria-label={t('timeline.yearLabel')}
            value={year}
            onChange={(e) => onChange(Number(e.target.value))}
          >
            {(years.includes(year) ? years : [year, ...years]).map((y) => (
              <option key={y} value={y}>
                {y}
              </option>
            ))}
          </select>
        )}
      </Field>
    </div>
  )
}

// ---------------------------------------------------------------------------

function ListView({ entries, year }: { entries: TimelineEntry[]; year: number }) {
  const { t, locale } = useI18n()
  const groups = useMemo(() => groupByYearMonth(entries), [entries])

  if (groups.length === 0) return <EmptyYear year={year} />

  return (
    <>
      {groups.map((g) => (
        <Card key={g.year} title={g.year} icon="memories">
          {g.months.map((m) => (
            <div key={m.month} className="stack stack--tight">
              <p className="tl__month">
                {fmtDate(`${m.month}-01`, 'MMMM', locale)} · {t('timeline.countInMonth', { n: m.items.length })}
              </p>
              <ul className="list">
                {m.items.map((e) => (
                  <li key={`${e.source}-${e.id}`} className="list__item">
                    <Icon name={e.isMilestone ? 'ring' : e.source === 'event' ? 'calendar' : 'memories'} size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{e.title}</strong>
                      <span className="card__hint">
                        {fmtDate(e.date, 'd MMMM', locale)} ·{' '}
                        {t(e.source === 'event' ? 'timeline.kind.event' : 'timeline.kind.memory')}
                        {e.isMilestone ? ` · ${t('timeline.markLabel')}` : ''}
                      </span>
                      {e.story && <span className="card__hint">{e.story}</span>}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </Card>
      ))}
    </>
  )
}

// ---------------------------------------------------------------------------

function HeatView({ year, counts }: { year: number; counts: Map<string, DayCount> }) {
  const { t, locale } = useI18n()
  const [picked, setPicked] = useState<string | null>(null)

  const weeks = useMemo(() => heatmapWeeks(year, counts), [year, counts])
  const months = useMemo(() => monthColumns(weeks), [weeks])
  const rows = useMemo(() => activeDays(counts), [counts])
  const cells = useMemo(() => weeks.flat(), [weeks])
  const selected = picked ? counts.get(picked) : undefined

  return (
    <Card title={t('timeline.heatTitle', { year })} icon="calendar">
      <p className="card__hint">{t('timeline.heatHint')}</p>

      {rows.length === 0 ? (
        <EmptyState icon="info" title={t('timeline.heatEmpty', { year })} hint={t('timeline.emptyYearHint')} />
      ) : (
        <>
          {/* The grid is decoration with keyboard access bolted on; the table
              below is the real, complete alternative (blueprint 04 §13). */}
          <div className="table-scroll">
            <div className="heat__months" aria-hidden="true">
              {months.map((m) => (
                <span key={m.month} style={{ gridColumnStart: m.column }}>
                  {fmtDate(`${year}-${String(m.month).padStart(2, '0')}-01`, 'MMM', locale)}
                </span>
              ))}
            </div>
            <div className="heat">
              {cells.map((cell, i) => (
                <HeatCellView
                  key={cell.date ?? `pad-${i}`}
                  cell={cell}
                  picked={picked === cell.date}
                  onPick={setPicked}
                />
              ))}
            </div>
          </div>

          <div className="heat__legend">
            <span>{t('timeline.less')}</span>
            {[0, 1, 2, 3, 4].map((l) => (
              <span key={l} className="heat__cell" data-level={l} aria-hidden="true" />
            ))}
            <span>{t('timeline.more')}</span>
          </div>

          <p className="card__hint" aria-live="polite">
            {picked && selected
              ? t('timeline.daySummary', {
                  date: fmtDate(picked, 'd MMMM yyyy', locale),
                  memories: selected.memories,
                  events: selected.events,
                  pair: selected.pairDays,
                })
              : t('timeline.dayNone')}
          </p>

          <details>
            <summary style={{ cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
              {t('timeline.seeNumbers')}
            </summary>
            <div className="table-scroll" style={{ marginTop: 8 }}>
              <table>
                <caption className="visually-hidden">{t('timeline.tableCaption', { year })}</caption>
                <thead>
                  <tr>
                    <th scope="col" style={cellHead}>{t('timeline.colDate')}</th>
                    <th scope="col" style={cellHead}>{t('timeline.colMemories')}</th>
                    <th scope="col" style={cellHead}>{t('timeline.colEvents')}</th>
                    <th scope="col" style={cellHead}>{t('timeline.colPair')}</th>
                    <th scope="col" style={cellHead}>{t('timeline.colTotal')}</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.date}>
                      <th scope="row" style={cell}>{fmtDate(r.date, 'd MMM', locale)}</th>
                      <td style={cell}>{r.count.memories}</td>
                      <td style={cell}>{r.count.events}</td>
                      <td style={cell}>{r.count.pairDays}</td>
                      <td style={cell}>{r.count.total}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </details>
        </>
      )}

      <p className="disclaimer">{t('timeline.heatNotAScore')}</p>
    </Card>
  )
}

function HeatCellView({
  cell,
  picked,
  onPick,
}: {
  cell: HeatCell
  picked: boolean
  onPick: (date: string) => void
}) {
  const { t, locale } = useI18n()

  if (!cell.date) return <span className="heat__cell heat__cell--pad" aria-hidden="true" />

  // Only days with something on them are controls. 365 tab stops per year would
  // make the keyboard path unusable, and an empty day has nothing to open.
  if (cell.count.total === 0) {
    return <span className="heat__cell" data-level={0} aria-hidden="true" />
  }

  const date = cell.date
  return (
    <button
      type="button"
      className="heat__cell"
      data-level={cell.level}
      aria-pressed={picked}
      onClick={() => onPick(date)}
      onFocus={() => onPick(date)}
    >
      <span className="visually-hidden">
        {t('timeline.dayCell', { date: fmtDate(date, 'd MMMM', locale), n: cell.count.total })}
      </span>
    </button>
  )
}

// ---------------------------------------------------------------------------

function MarksView({ memories, year }: { memories: Memory[]; year: number }) {
  const { t, locale } = useI18n()
  const today = new Date().toISOString().slice(0, 10)

  const marks = useMemo(
    () =>
      milestonesIn(
        memories
          .filter((m) => m.isMilestone)
          .map((m) => ({ id: m.id, title: m.title, date: m.date, ...(m.story ? { story: m.story } : {}) })),
        year,
      ),
    [memories, year],
  )

  return (
    <Card title={t('timeline.marksTitle', { year })} icon="ring">
      <p className="card__hint">{t('timeline.marksHint')}</p>
      {marks.length === 0 ? (
        <EmptyState
          icon="ring"
          title={t('timeline.marksEmpty')}
          hint={t('timeline.marksEmptyHint')}
          action={
            <Link className="btn btn--sm" to="/momen?baru=1">
              <Icon name="plus" size={16} /> {t('mem.save')}
            </Link>
          }
        />
      ) : (
        <ul className="list">
          {marks.map((m) => (
            <li key={m.id} className="list__item">
              <Icon name="ring" size={18} />
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{m.title}</strong>
                <span className="card__hint">
                  {fmtDate(m.markDate, 'd MMMM', locale)}
                  {m.years > 0 ? ` · ${t('timeline.marksSince', { date: fmtDate(m.date, 'd MMM yyyy', locale) })}` : ''}
                </span>
                {m.story && <span className="card__hint">{m.story}</span>}
              </span>
              <span className={`chip ${m.years === 0 ? 'chip--mint' : 'chip--lavender'}`}>
                {m.years === 0 ? t('timeline.marksOriginal') : t('timeline.marksYears', { n: m.years })}
              </span>
              <span className="chip">
                {m.markDate >= today ? t('timeline.marksUpcoming') : t('timeline.marksPassed')}
              </span>
            </li>
          ))}
        </ul>
      )}
    </Card>
  )
}

// ---------------------------------------------------------------------------

function EmptyYear({ year }: { year: number }) {
  const { t } = useI18n()
  return (
    <Card>
      <EmptyState icon="info" title={t('timeline.emptyYear', { year })} hint={t('timeline.emptyYearHint')} />
    </Card>
  )
}

const cellHead: React.CSSProperties = {
  textAlign: 'left',
  padding: '4px 6px',
  borderBottom: '1px solid var(--border)',
  fontWeight: 700,
}
const cell: React.CSSProperties = {
  textAlign: 'left',
  padding: '4px 6px',
  borderBottom: '1px solid var(--border)',
  fontWeight: 400,
}
